using Ember;
static class StudioTests
{
 public static void Run(Action<bool,string> assert)
 {
  assert(Rgb.Hsv(0).Hex=="#FF0000"&&Rgb.Hsv(1.0/3).Hex=="#00FF00"&&Rgb.Hsv(2.0/3).Hex=="#0000FF","wheel hue primaries");
  foreach(var color in new[]{"#FF5A1F","#0066FF","#000000","#FFFFFF","#7F4A09"}){var parsed=Rgb.Parse(color);var hsv=parsed.ToHsv();assert(Rgb.Hsv(hsv.Hue,hsv.Saturation,hsv.Value)==parsed,"HSV round trip "+color);}
  var effect=new CustomEffect{Name="Timer",Repeat=false,Steps={new(){Color="#FF0000",DurationMs=1000},new(){Color="#0000FF",DurationMs=1000,Transition=StepTransition.Fade}}};var player=new EffectPlayer();player.Start(effect,0);
  assert(player.Sample(.9).Hex=="#FF0000"&&player.Index==0,"timer holds initial color");assert(player.Sample(1.5).Hex=="#800080"&&player.Index==1,"fade interpolates at half duration");assert(player.Sample(2.1).Hex=="#0000FF"&&!player.Running,"one-shot stops on final color");
  effect.Repeat=true;effect.Steps[1].Transition=StepTransition.Cut;player.Start(effect,0);assert(player.Sample(4.5).Hex=="#FF0000"&&player.Index==0,"loop catches up to elapsed wall time");player.Start(effect,0);player.Pause(.5);assert(player.Sample(5).Hex=="#FF0000"&&player.Index==0,"pause freezes effect timeline");player.Resume(5);assert(player.Sample(5.4).Hex=="#FF0000"&&player.Sample(5.6).Hex=="#0000FF","resume preserves remaining duration");
  var gated=new CustomEffect{Name="Біт",Steps={new(){Color="#FF0000",DurationMs=500,Trigger=StepTrigger.MusicBeat},new(){Color="#00FF00",DurationMs=500,Trigger=StepTrigger.MusicBeat},new(){Color="#0000FF",DurationMs=500}}};player.Start(gated,0);assert(player.Sample(.2,true).Hex=="#FF0000"&&player.Sample(.7).Hex=="#FF0000","beat gate requires minimum time and a new beat");assert(player.Sample(1,true).Hex=="#00FF00"&&player.Index==1,"beat advances exactly one step");assert(player.Sample(1.4,true).Hex=="#00FF00"&&player.Sample(1.7,true).Hex=="#0000FF","beat gate respects each step minimum");gated.Steps[0].Color="#FFFFFF";assert(player.Effect!.Steps[0].Color=="#FF0000","playback snapshots remain independent");gated.Steps[0].Color="#FF0000";
  string path=Path.Combine(AppContext.BaseDirectory,"studio-test-"+Guid.NewGuid().ToString("N")+".json");try{
   EffectStore.Save(path,new[]{gated});var loaded=EffectStore.Load(path);assert(loaded[0].Id==gated.Id&&loaded[0].Steps[0].Trigger==StepTrigger.MusicBeat,"local persistence retains identities and timing");var invalid=gated.Clone();invalid.Steps[0].DurationMs=0;bool rejected=false;try{EffectStore.Save(path,new[]{invalid});}catch(ArgumentException){rejected=true;}assert(rejected&&EffectStore.Load(path)[0].Steps[0].DurationMs==500,"invalid save preserves existing file");
   var legacy=gated.Clone();legacy.Steps[0].Trigger=StepTrigger.MicrophoneSound;EffectStore.Save(path,new[]{legacy});assert(EffectStore.Load(path)[0].Steps[0].Trigger==StepTrigger.MicrophoneSound,"old PC microphone files retained without silent conversion");rejected=false;try{player.Start(legacy,0);}catch(ArgumentException){rejected=true;}assert(rejected,"legacy PC microphone playback requires explicit editing");
   string exported=EffectPack.Serialize(new[]{gated});var imported=EffectPack.Parse(exported);assert(imported.Count==1&&imported[0].Name=="Біт"&&imported[0].IsImported&&imported[0].Id!=gated.Id,"portable pack retains Unicode and adds independent local identity");assert(!exported.Contains("IsImported")&&!exported.Contains(gated.Id)&&EffectPack.Fingerprint(gated)==EffectPack.Fingerprint(imported[0]),"portable pack excludes local metadata and round-trips behavior");
   var merged=EffectPack.Merge(new[]{gated},imported,out int added);assert(added==0&&merged.Count==1&&!merged[0].IsImported,"identical own effect is not duplicated or reclassified");imported[0].Name="Новий";merged=EffectPack.Merge(new[]{gated},imported,out added);assert(added==1&&merged.Count==2&&merged[1].IsImported&&merged[1].Id!=imported[0].Id,"new import is tagged and receives a unique ID");EffectStore.Save(path,merged);assert(EffectStore.Load(path)[1].IsImported,"import category survives restart");merged=EffectPack.Merge(merged,imported,out added);assert(added==0&&merged.Count==2,"reimport does not add duplicates");
   EffectPack.Write(path,imported);assert(EffectPack.Read(path).Count==1,"file export is readable by importer");
   var baseJson=EffectPack.Serialize(new[]{gated});foreach(var invalidJson in new[]{baseJson.Replace("\"version\": 2","\"version\": 99"),baseJson.Replace("musicBeat","stripSound"),baseJson.Replace("#FF0000","red"),baseJson.Replace("500","0"),baseJson.Replace("\"repeat\": true","\"repeat\": \"true\""),baseJson.Replace("\"format\":","\"unknown\": 1, \"format\":"),baseJson.Replace("\"format\":","\"format\": \"ember-effects\", \"format\":"),baseJson.Replace("\"steps\": [","\"steps\": null, \"ignored\": [")}){rejected=false;try{EffectPack.Parse(invalidJson);}catch{rejected=true;}assert(rejected,"malformed pack rejected atomically");}
   rejected=false;try{EffectPack.Parse(new string(' ',EffectPack.MaxBytes+1));}catch{rejected=true;}assert(rejected,"oversize pack rejected");rejected=false;try{EffectPack.Serialize(new[]{legacy});}catch(ArgumentException){rejected=true;}assert(rejected,"legacy microphone trigger cannot escape into portable standard");
  }finally{File.Delete(path);File.Delete(path+".tmp");}
  var examples=EffectPack.Read(Path.Combine(AppContext.BaseDirectory,"Examples/Ember-Starter.ember.json"));assert(examples.Count==3&&examples.All(x=>x.IsPlayable),"shipped example pack passes the real importer");
  foreach(double dpi in new[]{1.0,1.25,1.5,2.0}){var size=WindowGeometry.Fit(1920,1040,dpi,dpi,1280,910,true);assert(size.Width*dpi<=1920&&size.Height*dpi<=1040&&size.Height<1040/dpi,"Full HD work area fit at scale "+dpi);var editor=WindowGeometry.Fit(1920,1040,dpi,dpi,1030,740,false);assert(editor.Width<=1030&&editor.Height<=740&&editor.Height*dpi<=1040,"effect editor fits scaled work area "+dpi);}var small=WindowGeometry.Fit(800,560,1.25,1.25,1280,910,true);assert(small.Width<=640&&small.Height<=448,"small monitor work area stays accessible");
  var captured=new List<EffectStep>();var recorder=new LiveEffectRecorder();recorder.Start(captured,new(255,0,0),10,StepTrigger.MusicBeat,StepTransition.Fade);recorder.Record(new(0,0,255),10.35,StepTrigger.Timer,StepTransition.Cut);recorder.Stop(11.2);assert(captured.Count==2&&captured[0].DurationMs==350&&captured[1].DurationMs==850&&!recorder.Active,"live recorder captures elapsed color intervals");assert(captured[0].Trigger==StepTrigger.MusicBeat&&captured[0].Transition==StepTransition.Fade,"recorder retains each selected trigger and transition");
  assert(WasapiAudio.CaptureConfiguration()==(0,0x20000),"only Windows output loopback can be opened");
  var f=new AudioFrame(.2,.5,.15,.1,.01,120,true,1,Enumerable.Repeat(.5,32).ToArray(),DateTime.UtcNow);foreach(var preset in ReactiveEffects.Music){var engine=new ReactiveEffects();var atBeat=engine.Render(preset.Id,new(255,90,31),1,f,true);var quiet=engine.Render(preset.Id,new(255,90,31),10,null,false);assert(atBeat!=default&&atBeat.R+atBeat.G+atBeat.B>quiet.R+quiet.G+quiet.B,"music preset follows real signal: "+preset.Id);}
  assert(ModeCatalog.Autonomous.Length==16&&ModeCatalog.Autonomous.Select(x=>x.Id).Distinct().Count()==16,"sixteen distinct autonomous choices");assert(ModeCatalog.Autonomous.Where(p=>p.Id is not ("STATIC" or "JUMP3" or "JUMP7" or "FADE3" or "FADE7")).Select(p=>ModeCatalog.ModeId(p.Id,2)).Distinct().Count()==11,"new ELK autonomous mode IDs are distinct");
  assert(Convert.ToHexString(Protocol.StripMicPower(true))=="7E040701FFFFFF00EF"&&Convert.ToHexString(Protocol.StripMicPower(false))=="7E040700FFFFFF00EF","controller microphone on/off packet fixtures");for(int mode=0;mode<4;mode++)assert(Convert.ToHexString(Protocol.StripMicMode(mode))==$"7E0503{128+mode:X2}04FFFF00EF","controller microphone EQ "+mode);assert(Convert.ToHexString(Protocol.StripMicSensitivity(35))=="7E040623FFFFFF00EF","controller microphone sensitivity fixture");
 }
}
